package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
/** Local manual review. No model invocation and no calendar write. */
final class ConversationWorkspaceDialog {
 final MainActivity owner; final LinearLayout box; final JSONObject state;
 ConversationWorkspaceDialog(MainActivity a){owner=a;box=new LinearLayout(a);box.setOrientation(1);box.setPadding(24,12,24,12);state=ConversationWorkspace.snapshot(a);}
 TextView text(String value){TextView v=new TextView(owner);v.setText(value);box.addView(v);return v;}
 EditText field(String label,String value){text(label);EditText e=new EditText(owner);e.setText(value);e.setSingleLine(true);box.addView(e);return e;}
 void send(JSONObject command){try{command.put("requestId",java.util.UUID.randomUUID().toString());ConversationWorkspace.submit(owner,command);text("グラスへ送信待ちです。反映後にこの画面を開き直して確認してください。まだ予定は登録していません。");}catch(Exception e){text("操作できません："+e.getMessage());}}
 void show(){Button correction=new Button(owner);correction.setText("直近の入力を訂正（送信しません）");correction.setOnClickListener(v->owner.beginRecentCorrection());box.addView(correction);text(state.optBoolean("connected")?"グラスと接続中":"グラスの状態が古い可能性があります。再接続して開き直してください");text("参照先："+state.optString("referenceMode","auto")+" "+state.optString("inboxTitle"));
 String referent=ConversationReferentPreview.label(state.optJSONObject("referent"));if(!referent.isEmpty())text(referent);
 String[] labels={"自動で参照を選ぶ","直近の画像を使う","画像を使わず話す"},modes={"auto","image","none"};for(int i=0;i<3;i++){final String mode=modes[i];Button b=new Button(owner);b.setText(labels[i]);b.setOnClickListener(v->{try{send(new JSONObject().put("action","reference").put("mode",mode).put("referenceAt",state.optLong("referenceAt")));}catch(Exception ignored){}});box.addView(b);}
 JSONObject recognition=state.optJSONObject("recognition");if(recognition!=null){text("認識："+recognition.optString("source")+" / "+recognition.optString("phase"));text(recognition.optString("text").isEmpty()?"認識文はまだありません。音が不明瞭な場合もあります。":recognition.optString("text"));}
 JSONObject draft=state.optJSONObject("calendarDraft");if(draft!=null)try{text(CalendarReviewSummary.describe(draft));Button duplicates=new Button(owner);duplicates.setText("保存済み候補の重複を確認（登録しません）");duplicates.setOnClickListener(v->{duplicates.setEnabled(false);new Thread(()->{String result;try{result=CalendarWriter.preview(owner,draft).optString("message");}catch(Exception e){result="重複候補を確認できません。まだ登録していません。";}final String message=result;owner.runOnUiThread(()->{duplicates.setEnabled(true);if(!owner.isDestroyed())text(message);});},"CalendarPreview").start();});box.addView(duplicates);text("予約候補の訂正（登録はしません）\n終日の終了日は最終日の翌日。時刻指定は例：2026-10-20T10:00:00+09:00");EditText calendar=field("カレンダー",draft.optString("calendar_name"));JSONArray events=draft.getJSONArray("events");java.util.List<EditText[]> fields=new java.util.ArrayList<>();java.util.List<CheckBox> days=new java.util.ArrayList<>();for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);text("予定 "+(i+1));EditText[] inputs={field("予定名",e.optString("title")),field("開始",e.optString("start")),field("終了",e.optString("end")),field("場所",e.optString("location"))};fields.add(inputs);CheckBox day=new CheckBox(owner);day.setText("終日");day.setChecked(e.optBoolean("all_day"));box.addView(day);days.add(day);}Button review=new Button(owner);review.setText("訂正してグラスで再確認");review.setOnClickListener(v->{try{JSONArray edited=new JSONArray();for(int i=0;i<fields.size();i++){EditText[] f=fields.get(i);edited.put(new JSONObject().put("title",f[0].getText()).put("start",f[1].getText()).put("end",f[2].getText()).put("location",f[3].getText()).put("all_day",days.get(i).isChecked()));}JSONObject next=new JSONObject().put("calendar_name",calendar.getText()).put("events",edited);String diff=CalendarReviewSummary.diff(draft,next);if(diff.equals("変更はありません。")){text(diff);return;}JSONObject command=new JSONObject().put("action","calendar_edit").put("baseAt",state.getLong("draftAt")).put("candidate",next);new AlertDialog.Builder(owner).setTitle("訂正する内容").setMessage(diff+"\n"+CalendarReviewSummary.describe(next)+"\nまだ登録しません").setPositiveButton("訂正候補を送る",(d,w)->send(command)).setNegativeButton("戻る",null).show();}catch(Exception e){text("入力内容を確認してください："+e.getMessage());}});box.addView(review);}catch(Exception e){text("候補を読み込めません。グラスで確認してください。");}
 text(state.optString("commandStatus"));ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("会話の参照・予約候補・認識文").setView(scroll).setPositiveButton("閉じる",null).show();}
}
